void merge_sort(std::vector<int> &a, int l, int r, int &count) {
    int m = (l + r) / 2;
    merge_sort(a, l, m, count);
    merge_sort(a, m + 1, r, count);
    int i = l, j = m + 1;
    while (i <= m && j <= r) {
        if (a[i] < a[j]) {
            temp.push_back(a[i++]);
        } else {
            temp.push_back(a[j++]);
            count += m - i + 1;
        }
    }
    std::cout << "merge [" << l << ".." << r << "]:";
    for (int k = l; k <= r; k++)
        std::cout << ' ' << a[k];
    std::cout << '\n';
}
